def count_status(rows):
    counts = {}
    for row in rows:
        key = row["status"]
        counts[key] = counts.get(key, 0) + 1
    return counts

def batch_cosine(queries,docs):
    import numpy as np
    q=np.asarray(queries,dtype=float);d=np.asarray(docs,dtype=float)
    if q.ndim!=2 or d.ndim!=2 or q.shape[1]!=d.shape[1]:raise ValueError('shape')
    qn=np.linalg.norm(q,axis=1,keepdims=True);dn=np.linalg.norm(d,axis=1,keepdims=True)
    q=np.divide(q,qn,out=np.zeros_like(q),where=qn!=0);d=np.divide(d,dn,out=np.zeros_like(d),where=dn!=0)
    return (q@d.T).tolist()

def previous_duration(df):
    s=df.sort_values(["test","build"]).groupby("test")["duration"].shift(1)
    return [None if __import__("pandas").isna(v) else float(v) for v in s]

def latest_health(rows):
    latest={}
    for r in sorted(rows,key=lambda r:r['run_id']):latest[(r['build_id'],r['test_id'])]=r
    selected=list(latest.values());total=len(selected);failed=sum(r['status']=='failed' for r in selected)
    return {'total':total,'failed':failed,'pass_rate':(total-failed)/total if total else 0}

def effect_pp(a,b):
    if not (0 <= a <= 1 and 0 <= b <= 1): raise ValueError("invalid proportion")
    return (b-a)*100

def mae(actual,predicted):
    if len(actual)!=len(predicted) or not actual: raise ValueError("invalid pair lengths")
    return sum(abs(a-b) for a,b in zip(actual,predicted))/len(actual)

def unusual(value,mean,sd,limit=3):
    if sd<=0: raise ValueError("positive spread required")
    return abs(value-mean)/sd > limit

def nll(probabilities):
    import math
    if not probabilities or any(not 0<p<=1 for p in probabilities):raise ValueError('probabilities')
    return -sum(math.log(p) for p in probabilities)/len(probabilities)

def causal_allowed(query_position,key_position):
    if min(query_position,key_position)<0:raise ValueError('position')
    return key_position<=query_position

def nucleus(probs,p):
    if not 0<p<=1: raise ValueError('p')
    out=[];mass=0
    for i,v in sorted(enumerate(probs),key=lambda x:-x[1]):
        out.append(i);mass+=v
        if mass>=p: break
    return out

def cost_usd(input_tokens,output_tokens,input_rate,output_rate):
    if min(input_tokens,output_tokens,input_rate,output_rate)<0: raise ValueError('negative')
    return (input_tokens*input_rate+output_tokens*output_rate)/1000000

def agreement(outputs):
    if not outputs:return 0
    return max(outputs.count(x) for x in set(outputs))/len(outputs)

def backoff(attempt,cap=8):
    if attempt<0: raise ValueError('attempt')
    return min(cap,2**attempt)

def assemble(events):
    import json
    if not events or events[-1].get('type')!='done': raise ValueError('incomplete')
    return json.loads(''.join(e.get('text','') for e in events if e.get('type')=='delta'))

def normalize(status,parsed):
    if status!='completed':return {'status':'incomplete','value':None}
    if parsed is None:return {'status':'invalid','value':None}
    return {'status':'ready','value':parsed}

def public_config(config):
    allowed={'model','sdk_version','prompt_revision','output_cap','mode'}
    return {k:v for k,v in config.items() if k in allowed}

def cost_per_success(costs,successes):
    if successes<=0:return None
    return sum(costs)/successes

def compare(base,candidate):
    if len(base)!=len(candidate): raise ValueError('paired lengths')
    return {'wins':sum(c and not b for b,c in zip(base,candidate)), 'losses':sum(b and not c for b,c in zip(base,candidate)), 'ties':sum(b==c for b,c in zip(base,candidate))}

def evidence_ids_valid(ids,sources):
    allowed={s['id'] for s in sources}
    return all(i in allowed for i in ids)

def valid_result(r):
    allowed={'PRODUCT_DEFECT','AUTOMATION_DEFECT','ENVIRONMENT','TEST_DATA','UNKNOWN'}
    return set(r)=={'category','evidence_ids'} and r['category'] in allowed and isinstance(r['evidence_ids'],list) and all(isinstance(x,str) for x in r['evidence_ids']) and (r['category']=='UNKNOWN' or bool(r['evidence_ids']))

def domain_valid(d,allowed):
    ids=d.get('evidence_ids',[])
    return set(ids)<=set(allowed) and (d.get('needs_review') is True if d.get('category')=='UNKNOWN' else bool(ids))

def dispatch_allowed(name,args,registry):
    spec=registry.get(name)
    return spec is not None and set(args)==set(spec)

def cosine(a,b):
    import math
    if len(a)!=len(b): raise ValueError('dimensions')
    na=math.sqrt(sum(x*x for x in a));nb=math.sqrt(sum(x*x for x in b))
    return sum(x*y for x,y in zip(a,b))/(na*nb) if na and nb else 0

def compatible_embeddings(left,right):
    keys=('model','dimension','normalize','prefix')
    return all(k in left and k in right and left[k]==right[k] for k in keys)

def authorized_topk(docs,tenant,k):
    if k<0: raise ValueError('k')
    return [d['id'] for d in sorted((d for d in docs if d['tenant']==tenant),key=lambda d:(-d['score'],d['id']))[:k]]

def upsert(points,new):
    by_id={p['id']:p for p in points}
    by_id[new['id']]=new
    return [by_id[k] for k in sorted(by_id)]

def chunks(words,size,overlap):
    if size<=0 or not 0<=overlap<size: raise ValueError('bounds')
    out=[];i=0
    while i<len(words):
        out.append(words[i:i+size])
        if i+size>=len(words): break
        i+=size-overlap
    return out

def citations_valid(cited,supplied,tenant,documents):
    by_id={d['id']:d for d in documents}
    return bool(cited) and all(i in supplied and i in by_id and by_id[i]['tenant']==tenant and not by_id[i].get('deleted') for i in cited)

def rrf(lists,c=60):
    if c<0: raise ValueError('c')
    scores={}
    for ranked in lists:
        for rank,doc in enumerate(dict.fromkeys(ranked),1):
            scores[doc]=scores.get(doc,0)+1/(c+rank)
    return sorted(scores,key=lambda d:(-scores[d],d))

def apply_event(state,event):
    prior=state.get(event['id'])
    if prior and event['version']<=prior['version']:return state.copy()
    return {**state,event['id']:{'version':event['version'],'deleted':event.get('deleted',False)}}

def retrieval_metrics(ranked,relevant,k):
    if k<=0: raise ValueError('k')
    top=ranked[:k];hits=len(set(top)&set(relevant))
    rr=next((1/i for i,d in enumerate(top,1) if d in relevant),0)
    return {'precision':hits/k,'recall':hits/len(set(relevant)) if relevant else 0,'mrr':rr}

def ndcg(grades,ideal,k):
    import math
    if k<=0:raise ValueError('k')
    def dcg(xs):return sum((2**r-1)/math.log2(i+2) for i,r in enumerate(xs[:k]))
    best=dcg(sorted(ideal,reverse=True))
    return dcg(grades)/best if best else 0

def judge_errors(human,judge):
    if len(human)!=len(judge) or not human:raise ValueError('paired labels')
    return {'agreement':sum(h==j for h,j in zip(human,judge))/len(human),'false_accepts':sum(j and not h for h,j in zip(human,judge)),'false_rejects':sum(h and not j for h,j in zip(human,judge))}

def fixture_path(identifier):
    if not identifier.startswith('F') or not identifier[1:].isdigit():raise ValueError('invalid id')
    return 'fixtures/'+identifier+'.json'

def lifecycle_valid(events):
    required=['connect','initialize','discover','call','close']
    return events==required

def validate_call(name,args,allowed):
    if name not in allowed:return False
    if name=='read_failure':return set(args)=={'failure_id'} and args['failure_id'].startswith('F') and args['failure_id'][1:].isdigit()
    if name=='search_history':return set(args)=={'query'} and isinstance(args['query'],str) and len(args['query'])<=1000
    return False

def allocate(total,requests):
    if total<0 or any(r<0 for r in requests) or sum(requests)>total:raise ValueError('budget')
    return total-sum(requests)

def context(messages,budget):
    if budget<0:raise ValueError('budget')
    kept=[];used=0
    for m in reversed(messages):
        if used+len(m)>budget:break
        kept.append(m);used+=len(m)
    return list(reversed(kept))

def resolve(subject,followup,is_reference):
    if is_reference and not subject:return {'status':'clarification','query':None}
    return {'status':'ready','query':subject+' '+followup if is_reference else followup}

def retain_messages(messages,limit):
    if limit<0:raise ValueError('limit')
    return messages[-limit:] if limit else []

def response_valid(r):
    status=r.get('status')
    if status=='answered':return bool(r.get('answer')) and bool(r.get('citations'))
    if status=='abstained':return r.get('answer') is None and not r.get('citations')
    if status=='clarification':return bool(r.get('answer')) and not r.get('citations')
    return False

def trace_metrics(trace):
    sig=[(e['tool'],str(sorted(e.get('args',{}).items()))) for e in trace]
    return {'steps':len(trace),'denied':sum(not e.get('authorized',False) for e in trace),'repeated':len(sig)-len(set(sig))}

def verdict(results,expected_ids):
    ids=[r['id'] for r in results]
    return len(ids)==len(set(ids)) and set(ids)==set(expected_ids) and all(r.get('passed') is True for r in results)

def redact_nested(value):
    blocked={'api_key','authorization','password','token'}
    if isinstance(value,dict):return {k:('[REDACTED]' if k.lower() in blocked else redact_nested(v)) for k,v in value.items()}
    if isinstance(value,list):return [redact_nested(v) for v in value]
    return value

def catches_mutant(test_inputs,expected,mutant):
    if len(test_inputs)!=len(expected):raise ValueError('length')
    return any(mutant(x)!=y for x,y in zip(test_inputs,expected))

def imports_in(code):
    import ast
    tree=ast.parse(code);out=[]
    for node in ast.walk(tree):
        if isinstance(node,ast.Import):out.extend(n.name.split('.')[0] for n in node.names)
        elif isinstance(node,ast.ImportFrom) and node.module:out.append(node.module.split('.')[0])
    return sorted(set(out))

def normalize_adapter(result):
    required={'category','evidence_ids','needs_review'}
    if not required<=set(result):raise ValueError('adapter contract')
    return {k:result[k] for k in sorted(required)}

def required_build_files(files):
    required={'local-labs/quality','local-labs/fastapi','datasets'}
    return required<=set(files)

def deployable(checks):
    required={'content','unit','integration','build','evaluation'}
    return required<=set(checks) and all(checks[k]=='passed' for k in required)

def redact(record):
    blocked={'authorization','api_key','password','token'}
    return {k:('[REDACTED]' if k.lower() in blocked else v) for k,v in record.items()}

def safe_attributes(attrs):
    forbidden={'authorization','api_key','password','raw_prompt'}
    return not any(k.lower() in forbidden for k in attrs)

def cost_per_success(costs,successes):
    if successes<=0:return None
    if any(c<0 for c in costs):raise ValueError('cost')
    return sum(costs)/successes

def remaining_budget(total,usage):
    if total<0 or any(u<0 for u in usage):raise ValueError('usage')
    return max(0,total-sum(usage))

def percentile(values,p):
    import math
    if not values or not 0<p<=100:raise ValueError('bounds')
    return sorted(values)[math.ceil(p/100*len(values))-1]

def throughput(completed,seconds):
    if completed<0 or seconds<=0:raise ValueError('bounds')
    return completed/seconds

def failure_contract(fault,observed):
    expected={'timeout':'unavailable','missing_context':'abstained','unsafe_write':'denied','loop':'stopped'}
    return fault in expected and observed==expected[fault]

def compatible(a,b):
    keys=('schema','embedding_model','dimension','tokenizer')
    return all(k in a and k in b and a[k]==b[k] for k in keys)

def manifest_complete(manifest):
    required={'code','dataset','prompt','model','index','schema','evaluation'}
    return required<=set(manifest) and all(isinstance(manifest[k],str) and bool(manifest[k]) for k in required)

def lora_params(input_dim,output_dim,rank):
    if min(input_dim,output_dim,rank)<=0:raise ValueError('dimensions')
    return rank*(input_dim+output_dim)

def adapter_status(initialized,trained,evaluated):
    if evaluated and not trained:raise ValueError('evaluation requires trained artifact')
    if trained and not initialized:raise ValueError('training requires initialization')
    return 'evaluated' if evaluated else 'trained' if trained else 'initialized' if initialized else 'absent'

def design_gate(evidence):
    required={'authorization','evaluation','failure_recovery','latency','rollback'}
    return required<=set(evidence) and all(bool(evidence[k]) for k in required)
